input.sparql:
SELECT ?s ?p ?o WHERE {
  ?s a brick:Zone .
  ?s rdfs:label ?lbl .
  FILTER(CONTAINS(?lbl, "Zone_F2_Z01") || CONTAINS(?lbl, "Core") || CONTAINS(?lbl, "core") || CONTAINS(?lbl, "Z0") || CONTAINS(?lbl, "Z1") || CONTAINS(?lbl, "Z2") || CONTAINS(?lbl, "Z3"))
}

SELECT ?s ?p ?o WHERE {
  ?s a brick:AirTemperat .
  ?s rdfs:label ?lbl .
} LIMIT 30

SELECT ?s ?cls WHERE {
  ?s a brick:Zone .
  ?s a ?cls .
} LIMIT 50

SELECT ?s WHERE {
  ?s brick:hasPart ?z .
  ?z a ?cls .
  FILTER(CONTAINS(STR(?z), "F2"))
} LIMIT 50

SELECT ?p ?cls ?ts WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z01> brick:hasPoint ?p .
  ?p a ?cls .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts . }
} LIMIT 100

