  <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z02> brick:hasPoint ?p .
  ?p a ?cls .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts . }
} LIMIT 100
